/**
 * @description Follow-up calls: the middleware's callback for an outbound send (stores the body, sets the status
 * and reference, runs the event's response handler) and the status of an earlier inbound call.
 * @group Integration Hub
 */
public with sharing class IntegrationHubCallback {

    private static final Set<String> GOOD = new Set<String>{ 'SUCCESS', 'ACCEPTED', 'OK', 'CREATED', 'COMPLETED' };
    private static final Set<String> BAD = new Set<String>{ 'FAILED', 'REJECTED', 'ERROR' };

    /**
     * @description Handles PATCH .../callback/{transactionId}.
     * @param transactionId the transaction Id from the URL
     * @param body the callback JSON
     * @return the answer
     */
    public static IntegrationHubInbound.Response handle(String transactionId, String body) {
        if (IntegrationHubInbound.callerConnections().isEmpty()) {
            return IntegrationHubInbound.answer(403, IntegrationHubInbound.error('This user is not an inbound user of an active connection.'));
        }
        Id txnId = toTransactionId(transactionId);
        IH_Transaction__c t = txnId == null ? null : (IH_Transaction__c) IntegrationHubData.queryFirst(
            'SELECT Id, Name, Event__c, Direction__c, Status__c, Related_Record_Id__c, External_Reference_Id__c, Callback_Body__c '
            + 'FROM IH_Transaction__c WHERE Id = :id LIMIT 1', new Map<String, Object>{ 'id' => txnId });
        Integer problem = callbackProblem(t == null ? null : String.isBlank(t.Direction__c) ? '' : t.Direction__c, body);
        if (problem != null) {
            return IntegrationHubInbound.answer(problem, IntegrationHubInbound.error(problemMessage(problem, transactionId)));
        }
        Map<String, Object> data = IntegrationHubInbound.parseObject(body);
        t.Callback_Body__c = IntegrationHub.clip(body, IntegrationHubBodyFiles.FIELD_MAX);
        applyStatus(t, data);
        Boolean background = runHandler(t, body);
        IntegrationHubData.updateAll(new List<IH_Transaction__c>{ t });
        IntegrationHubBodyFiles.save(new List<ContentVersion>{
            IntegrationHubBodyFiles.fileFor(t.Id, IntegrationHubBodyFiles.CALLBACK_PREFIX + t.Name, body) });
        Map<String, Object> answer = new Map<String, Object>{ 'transactionId' => t.Id, 'status' => t.Status__c };
        if (background) {
            IntegrationHubBusiness.enqueue(new List<Id>{ t.Id });
            answer.put('business', IntegrationHubBusiness.PROCESSING);
        }
        return IntegrationHubInbound.answer(200, answer);
    }

    /**
     * @description Result of an earlier call.
     * @param transactionId the transaction Id
     * @return the answer
     */
    public static IntegrationHubInbound.Response status(String transactionId) {
        if (IntegrationHubInbound.callerConnections().isEmpty()) {
            return IntegrationHubInbound.answer(403, IntegrationHubInbound.error('This user is not an inbound user of an active connection.'));
        }
        Id txnId = toTransactionId(transactionId);
        IH_Transaction__c t = txnId == null ? null : (IH_Transaction__c) IntegrationHubData.queryFirst(
            'SELECT Id, Status__c, Related_Record_Id__c, Error_Message__c FROM IH_Transaction__c WHERE Id = :id LIMIT 1',
            new Map<String, Object>{ 'id' => txnId });
        if (t == null) {
            return IntegrationHubInbound.answer(404, IntegrationHubInbound.error('Transaction not found: ' + transactionId));
        }
        return IntegrationHubInbound.answer(200, new Map<String, Object>{
            'transactionId' => t.Id, 'status' => t.Status__c, 'recordId' => t.Related_Record_Id__c, 'error' => t.Error_Message__c });
    }

    /**
     * @description A transaction Id from text, or null when it is not one.
     * @param value the text
     * @return the Id, or null
     */
    public static Id toTransactionId(String value) {
        try {
            Id candidate = String.isBlank(value) ? null : Id.valueOf(value.trim());
            return candidate != null && candidate.getSObjectType() == IH_Transaction__c.SObjectType ? candidate : null;
        } catch (StringException e) {
            return null;
        }
    }

    /**
     * @description Checks a callback before it is applied, in answer order: no transaction 404, inbound 409, body not a
     * JSON object 400.
     * @param direction the transaction's direction ('' when blank), or null when no transaction was found
     * @param body the callback body
     * @return the HTTP status code of the problem, or null when the callback can be applied
     */
    @TestVisible
    private static Integer callbackProblem(String direction, String body) {
        if (direction == null) {
            return 404;
        }
        if (direction == IntegrationHub.INBOUND) {
            return 409;
        }
        return IntegrationHubInbound.parseObject(body) == null ? 400 : null;
    }

    /**
     * @description The error text for a callback problem code.
     * @param code 404, 409 or 400
     * @param transactionId the transaction Id from the URL
     * @return the message
     */
    @TestVisible
    private static String problemMessage(Integer code, String transactionId) {
        if (code == 404) {
            return 'Transaction not found: ' + transactionId;
        }
        return code == 409 ? 'Callbacks are only for outbound transactions.' : 'The body must be a JSON object.';
    }

    /**
     * @description Maps a callback status word to a transaction status: SUCCESS, ACCEPTED, OK, CREATED, COMPLETED give
     * Success; FAILED, REJECTED, ERROR give Failed; anything else gives null (status unchanged). Case and spaces are ignored.
     * @param value the status from the callback
     * @return Success, Failed or null
     */
    @TestVisible
    private static String mapStatus(String value) {
        String status = value == null ? '' : value.trim().toUpperCase();
        if (GOOD.contains(status)) {
            return IntegrationHub.STATUS_SUCCESS;
        }
        return BAD.contains(status) ? IntegrationHub.STATUS_FAILED : null;
    }

    private static void applyStatus(IH_Transaction__c t, Map<String, Object> data) {
        String status = data.get('status') == null ? '' : String.valueOf(data.get('status')).trim().toUpperCase();
        if (data.get('reference') != null) {
            t.External_Reference_Id__c = IntegrationHub.clip(String.valueOf(data.get('reference')), 255);
        }
        String mapped = mapStatus(status);
        if (mapped == IntegrationHub.STATUS_SUCCESS) {
            t.Status__c = IntegrationHub.STATUS_SUCCESS;
            t.Completed_At__c = System.now();
            t.Error_Message__c = null;
            t.Error_Summary__c = null;
        } else if (mapped == IntegrationHub.STATUS_FAILED) {
            t.Status__c = IntegrationHub.STATUS_FAILED;
            IntegrationHub.setError(t, data.get('message') == null ? 'Callback reported ' + status : String.valueOf(data.get('message')));
        }
    }

    /* Runs the response handler now, or (Business Data In Response) marks the transaction for the background job and returns true. */
    private static Boolean runHandler(IH_Transaction__c t, String body) {
        IH_Event__c ev = (IH_Event__c) IntegrationHubData.queryFirst(
            'SELECT Id, Response_Handler_Class__c, Business_Data_In_Response__c FROM IH_Event__c WHERE Id = :id LIMIT 1',
            new Map<String, Object>{ 'id' => t.Event__c });
        if (ev == null || String.isBlank(ev.Response_Handler_Class__c)) {
            return false;
        }
        if (ev.Business_Data_In_Response__c == true) {
            t.Business_Status__c = IntegrationHubBusiness.PROCESSING;
            return true;
        }
        IntegrationHub.ResponseContext ctx = new IntegrationHub.ResponseContext();
        ctx.txn = t;
        ctx.transactionId = t.Id;
        ctx.relatedRecordId = t.Related_Record_Id__c;
        ctx.body = body;
        ctx.isCallback = true;
        ctx.data = IntegrationHubBusiness.dataOf(body);
        String error = IntegrationHubOutcome.runHandler(ev.Response_Handler_Class__c, ctx);
        if (error != null) {
            IntegrationHubOutcome.failPermanent(t, error);
        }
        return false;
    }
}
